// Explain this mix (P-019, UI-16): the mix in words. Every sentence is a fixed pattern filled with values of the
// project; nothing is generated by a model and nothing is judged. Reasons are the assistant's own notes, quoted.
import type { Fx } from "../../bindings/Fx";
import type { MixLevels } from "../../bindings/MixLevels";
import type { Project } from "../../bindings/Project";
import type { ReturnFx } from "../../bindings/ReturnFx";
import type { Track } from "../../bindings/Track";
import { formatDb, formatPan } from "../../shared/format";
import { INFO, blockName, blockState, blockSummary, hzText, playsIn, sidechainsOf } from "../fx";
import { FAMILY_LABEL, FAMILY_ORDER, familyName, familyOf, membersOf, parentOf, playsBetween, sectionFacts, sectionGroups, tintOf } from "./model";

// ---------- the pieces a text is made of ----------
/** A run of text: plain, strong, a name (a chip that selects the element), or a term of the glossary. */
export type Part = string | { b: string } | { id: string; name: string; tint: string } | { term: string; text: string } | { tone: "ai" | "acc"; text: string };
export interface Bar {
  label: string;
  /** 0..1 */
  value: number;
  text: string;
  tint: string | null;
  accent: boolean;
}
export interface Step {
  sig: string;
  state: "on" | "neutral";
  /** Tint of the track a keyed block listens to. */
  keyTint: string | null;
  name: string;
  value: string;
  body: Part[];
}
export type Block =
  | { kind: "p"; parts: Part[]; faint?: boolean }
  | { kind: "tags"; tags: { text: string; tone: "ai" | null }[] }
  | { kind: "item"; icon: "group" | "wave" | "right" | null; head: Part[]; hint: string | null; body: Part[] }
  | { kind: "bars"; bars: Bar[] }
  | { kind: "pan"; dots: { id: string; name: string; tint: string; pan: number }[] }
  | { kind: "steps"; steps: Step[] }
  | { kind: "note"; number: number | null; title: string; text: string; foot: string | null }
  | { kind: "pending"; text: string };
export interface DocSection {
  id: string;
  /** Short name for the navigation. */
  nav: string;
  title: string;
  hint: string | null;
  blocks: Block[];
}
export interface Doc {
  title: string;
  sections: DocSection[];
}

// ---------- glossary (UI-16): one sentence per term ----------
export const GLOSSARY: Record<string, string> = {
  group: "A group gathers several tracks into one channel, so they can be treated and moved together.",
  "shared effect": "A shared effect (a return) is one reverb or delay that several tracks feed by sending it a copy of themselves.",
  send: "A send is a copy of a track that goes to a shared effect; the track itself goes on as before.",
  sidechain: "A sidechain lets one track control an effect on another: the effect reacts to what it listens to, not to what it processes.",
  compressor: "A compressor turns the loud moments down, so quiet and loud parts end up closer. The ratio says how firmly.",
  "parallel compressor": "Parallel compression blends a heavily compressed copy with the untouched sound: more body, with the hits intact.",
  "mix bus": "The mix bus is where every track, group and shared effect meets: what comes out of it is the mix.",
  automation: "Automation changes a control along the song, by itself, following a line drawn over time.",
  "high-pass": "A high-pass filter removes what is below a frequency and lets the rest through.",
  "low-pass": "A low-pass filter removes what is above a frequency and lets the rest through.",
  EQ: "An EQ makes chosen ranges of frequencies louder or quieter.",
  LU: "LU is a difference in loudness as the ear hears it; 1 LU is 1 dB.",
  LUFS: "LUFS measures loudness as the ear hears it, over time. Less negative is louder.",
  dry: "Dry is the sound with no reverb or delay on it; wet is the sound of the effect.",
};
const term = (t: string, key = t): Part => ({ term: key, text: t });
const b = (t: string): Part => ({ b: t });
const nm = (t: Track): Part => ({ id: t.id, name: t.name, tint: tintOf(t) });

/** Tagged template for a run of text: parts go in as they are, arrays are spliced. */
function tx(strings: TemplateStringsArray, ...vals: (Part | Part[] | number)[]): Part[] {
  const out: Part[] = [];
  strings.forEach((s, i) => {
    if (s) out.push(s);
    const v = vals[i];
    if (v === undefined) return;
    if (Array.isArray(v)) out.push(...v);
    else out.push(typeof v === "number" ? String(v) : v);
  });
  return out;
}
/** "A", "A and B", "A, B and C" over parts. */
function list(items: Part[], more = 0): Part[] {
  const out: Part[] = [];
  items.forEach((x, i) => {
    if (i) out.push(i === items.length - 1 && !more ? " and " : ", ");
    out.push(x);
  });
  if (more) out.push(` and ${more} more`);
  return out;
}
const names = (ts: Track[], max = 6): Part[] => (ts.length > max ? list(ts.slice(0, max - 1).map(nm), ts.length - (max - 1)) : list(ts.map(nm)));
const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const n1 = (v: number) => Number(v.toFixed(1)).toString().replace("-", "−");
const abs1 = (v: number) => n1(Math.abs(v));
const dB = (v: number) => `${formatDb(v)} dB`;
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
/** A block's name inside a sentence: "compressor", "EQ 2". */
const low = (name: string) => (/^[A-Z]{2}/.test(name) ? name : name.charAt(0).toLowerCase() + name.slice(1));
/** A musical value as words: "1/8." is a dotted 1/8 note. */
const noteText = (sync: string) => (sync.endsWith(".") ? `dotted ${sync.slice(0, -1)} note` : sync.endsWith("t") || sync.endsWith("T") ? `${sync.slice(0, -1)} note triplet` : `${sync} note`);

// ---------- what a block does, in plain words ----------
/** What an EQ band does to the sound: the word depends on where it is and on the direction. */
function eqWord(hz: number, gain: number): string {
  const up = gain > 0;
  if (hz < 100) return up ? "more weight" : "less rumble";
  if (hz < 350) return up ? "more body" : "less mud";
  if (hz < 900) return up ? "more fullness" : "less boxiness";
  if (hz < 2500) return up ? "more bite" : "less nasal tone";
  if (hz < 5000) return up ? "more presence" : "less edge";
  if (hz < 9000) return up ? "more brightness" : "less harshness";
  return up ? "more air" : "less hiss";
}
const rateText = (sync: string | null, hz: number) => (sync ? `every ${noteText(sync)}` : `${n1(hz)} times a second`);

/** One sentence on what a block of a chain does (UI-16). `p` resolves the names of what it listens to. */
export function blockWords(fx: Fx, p: Project): Part[] {
  const src = sidechainsOf(fx)
    .map((id) => p.tracks.find((t) => t.id === id))
    .filter((t): t is Track => !!t);
  switch (fx.type) {
    case "hpf":
      return [`Removes what is below ${hzText(fx.freq_hz)}: rumble and bumps that only take up room.`];
    case "lpf":
      return [`Removes what is above ${hzText(fx.freq_hz)}: a darker, softer top.`];
    case "eq": {
      const bands = fx.bands.filter((x) => x.enabled && Math.abs(x.gain_db) >= 0.25);
      if (!bands.length) return ["On, but every band is flat: it changes nothing."];
      return [`${cap(bands.map((x) => `${eqWord(x.freq_hz, x.gain_db)} (${formatDb(x.gain_db)} dB at ${hzText(x.freq_hz)})`).join(", "))}.`];
    }
    case "compressor":
      if (src.length) return tx`Listens to ${nm(src[0])} through a ${term("sidechain")}: each time ${src[0].name} plays, this is turned down for a moment, then let back.`;
      if (fx.mix < 1) return tx`A ${term("parallel compressor")}: a firmly squeezed copy (${n1(fx.ratio)}:1) is blended in at ${Math.round(fx.mix * 100)} %, for more body with the hits intact.`;
      return [`Turns the loudest moments down so the quiet ones are heard: ${n1(fx.ratio)}:1 above ${n1(fx.threshold_db)} dB.`];
    case "saturation":
      return [`Adds harmonics (${fx.character}, ${n1(fx.drive_db)} dB of drive): a denser, slightly rougher sound.`];
    case "gate":
      return [`Turns the track down by ${abs1(fx.range_db)} dB whenever it falls below ${n1(fx.threshold_db)} dB: less spill between the notes.`];
    case "deesser":
      return [`Tames the sharp “s” sounds around ${hzText(fx.freq_hz)}, only when they jump out.`];
    case "dynamic_eq": {
      const bands = fx.bands.filter((x) => x.enabled);
      if (!bands.length) return ["On, but no band is set: it changes nothing."];
      const one = bands[0];
      if (src.length) return tx`${one.range_db < 0 ? "Dips" : "Lifts"} ${hzText(one.freq_hz)} by up to ${abs1(one.range_db)} dB only while ${nm(src[0])} plays, to leave room for it.`;
      return [`An EQ that moves only when needed: ${bands.map((x) => `${x.range_db < 0 ? "cuts" : "lifts"} ${hzText(x.freq_hz)} by up to ${abs1(x.range_db)} dB`).join(", ")}.`];
    }
    case "transient": {
      const a = Math.abs(fx.attack_db) >= 0.25 ? `${fx.attack_db > 0 ? "sharpens" : "softens"} the start of each note (${formatDb(fx.attack_db)} dB)` : "";
      const s = Math.abs(fx.sustain_db) >= 0.25 ? `${fx.sustain_db > 0 ? "lengthens" : "shortens"} what rings after it (${formatDb(fx.sustain_db)} dB)` : "";
      return [a || s ? `${cap([a, s].filter(Boolean).join(" and "))}.` : "On, but set flat: it changes nothing."];
    }
    case "clipper":
      return [`Shaves the tallest peaks above ${n1(fx.threshold_db)} dBFS, so the track can sit louder without jumping out.`];
    case "multiband":
      return [`Compresses ${fx.bands.length} ranges of frequencies separately, each with its own settings.`];
    case "exciter":
      return [`Adds new high harmonics above ${hzText(fx.freq_hz)}: a sparkle an EQ cannot give.`];
    case "bass_enhancer":
      return [`Adds harmonics of the notes below ${hzText(fx.freq_hz)}, so the low end is heard on small speakers too.`];
    case "width":
      if (fx.width > 1.02) return [`Makes the stereo image wider (${Math.round(fx.width * 100)} %).`];
      if (fx.width < 0.02) return ["Makes the sound mono."];
      if (fx.width < 0.98) return [`Makes the stereo image narrower (${Math.round(fx.width * 100)} %).`];
      return ["On, but at 100 %: it changes nothing."];
    case "modulation":
      return [`${cap(fx.mode)}: a slow movement inside the sound, ${rateText(fx.sync, fx.rate_hz)}.`];
    case "tremolo":
      return [fx.mode === "autopan" ? `Moves the sound from side to side, ${rateText(fx.sync, fx.rate_hz)}.` : `Makes the level pulse, ${rateText(fx.sync, fx.rate_hz)}.`];
    case "harmonizer": {
      const v = fx.voices.filter((x) => x.enabled);
      return [v.length ? `Adds ${plural(v.length, "copy", "copies")} at another pitch (${v.map((x) => `${x.semitones > 0 ? "+" : ""}${Math.round(x.semitones)}`).join(", ")} semitones).` : "On, but no voice is set: it changes nothing."];
    }
    case "doubler":
      return ["Adds a slightly detuned copy, like a second take of the same part."];
  }
}

/** What a return's processor is, as a sentence. */
export function returnWords(fx: ReturnFx): string {
  if (fx.type === "reverb") {
    const pre = fx.predelay_ms >= 1 ? `, starting ${Math.round(fx.predelay_ms)} ms after the sound` : "";
    return `${fx.algorithm === "hall" ? "A hall" : `A ${fx.algorithm}`} reverb with a ${n1(fx.decay_s)} s tail${pre}, kept between ${hzText(fx.hpf_hz)} and ${hzText(fx.lpf_hz)}.`;
  }
  const every = fx.sync ? `every ${noteText(fx.sync)}` : `every ${Math.round(fx.time_ms)} ms`;
  return `A ${fx.mode === "ping_pong" ? "ping-pong " : ""}delay${fx.character === "tape" ? " with a tape sound" : ""}: it repeats what it receives ${every}, each repeat at ${Math.round(fx.feedback * 100)} % of the one before.`;
}
const returnKind = (r: Track) => (r.ret?.type === "delay" ? "delay" : "reverb");

// ---------- facts shared by the texts ----------
const audioOf = (p: Project) => p.tracks.filter((t) => t.kind === "audio");
const groupsOf = (p: Project) => p.tracks.filter((t) => t.kind === "group");
const returnsOf = (p: Project) => p.tracks.filter((t) => t.kind === "return");
const sendersOf = (p: Project, r: Track) =>
  p.tracks
    .flatMap((t) => t.sends.filter((s) => s.target === r.id).map((s) => ({ t, db: s.level_db })))
    .sort((a, z) => z.db - a.db);
/** Every "listens to" of the project: the listener, its block, the source. */
function keysOf(p: Project): { t: Track; block: string; fx: Fx; src: Track }[] {
  return p.tracks.flatMap((t) =>
    t.chain.blocks
      .filter((x) => blockState(x.fx) === "on")
      .flatMap((x) =>
        sidechainsOf(x.fx).flatMap((id) => {
          const src = p.tracks.find((s) => s.id === id);
          return src ? [{ t, block: blockName(t.chain, x.id), fx: x.fx, src }] : [];
        }),
      ),
  );
}
const working = (t: Track) => t.chain.blocks.filter((x) => blockState(x.fx) === "on");
const hasLevels = (l: MixLevels | null): l is MixLevels => !!l && l.mix_lufs !== null && l.families.some((f) => f.level_lu !== null);
const lufs = (v: number) => `${n1(v)} LUFS`;
/** A level in LU as a bar: −30 LU and below is empty, the loudest of the set is full. */
const barOf = (lu: number, top: number) => Math.max(0.04, Math.min(1, 1 - (top - lu) / 30));
/** Mean loudness of a set of sections (they are repeats of one another). */
function meanLufs(l: MixLevels, ids: string[]): number | null {
  const v = l.sections.filter((s) => ids.includes(s.id) && s.lufs !== null).map((s) => s.lufs!);
  return v.length ? v.reduce((a, x) => a + x, 0) / v.length : null;
}
const clock = (frames: number, rate: number) => {
  const s = Math.floor(frames / rate);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};
const isAre = (plural: boolean) => (plural ? "are" : "is");

function reasonsOf(p: Project): Block[] {
  const out: Block[] = [];
  if (p.ai.summary) out.push({ kind: "note", number: null, title: "The assistant’s summary", text: p.ai.summary, foot: null });
  for (const n of p.ai.notes) {
    const t = n.track ? p.tracks.find((x) => x.id === n.track) : undefined;
    out.push({ kind: "note", number: n.number, title: t?.name ?? "The whole mix", text: n.text, foot: null });
  }
  return out;
}
const REASONS_FOOT = "Reasons are the assistant’s own words, kept with the changes it made. A change made by hand has no reason attached.";

// ---------- the whole mix ----------
export function explainMix(p: Project, levels: MixLevels | null): Doc {
  const audio = audioOf(p);
  const groups = groupsOf(p);
  const returns = returnsOf(p);
  const keys = keysOf(p);
  const rate = p.sample_rate ?? 48000;
  const sections: DocSection[] = [];
  const untouched = !groups.length && !returns.some((r) => sendersOf(p, r).length) && !p.tracks.some((t) => working(t).length) && audio.every((t) => Math.abs(t.chain.pan) < 0.02);
  const fams = hasLevels(levels) ? levels.families.filter((f) => f.level_lu !== null).sort((a, z) => z.level_lu! - a.level_lu!) : [];
  const secs = sectionGroups(p);
  const facts = secs.map((s) => sectionFacts(p, s.name)!);

  // In short.
  {
    const parts: Part[] = [];
    if (!audio.length) parts.push("There are no tracks yet: import audio to start a mix.");
    else if (untouched) parts.push(b("Nothing has been shaped yet."), ` ${audio.length === 1 ? "The track goes" : `All ${audio.length} tracks go`} straight to the mix bus at the level of ${audio.length === 1 ? "its file" : "their files"}. There are no groups, nothing is sent to a shared effect, and every chain is empty.`);
    else {
      parts.push(b(plural(audio.length, "track")), ` reach${audio.length === 1 ? "es" : ""} the mix bus`);
      if (groups.length) parts.push(" through ", b(plural(groups.length, "group")));
      if (returns.length) parts.push(` and share${audio.length === 1 ? "s" : ""} `, b(plural(returns.length, "effect")));
      parts.push(".");
    }
    if (fams.length > 1) parts.push(` ${familyName(fams[0].name)} ${isAre(FAMILY_LABEL[fams[0].name]?.plural ?? true)} in front, ${n1(fams[0].level_lu! - fams[1].level_lu!)} LU above ${familyName(fams[1].name).toLowerCase()}.`);
    if (keys.length) parts.push(...tx` ${nm(keys[0].t)} steps back each time ${nm(keys[0].src)} plays.`);
    const wide = audio.filter((t) => Math.abs(t.chain.pan) >= 0.5);
    if (wide.length && wide.length < audio.length) parts.push(...tx` ${names(wide, 4)} ${wide.length === 1 ? "sits" : "sit"} to the sides; the rest ${audio.length - wide.length === 1 ? "stays" : "stay"} in or near the centre.`);
    if (hasLevels(levels) && secs.length > 1) {
      const loud = secs.map((s) => ({ s, v: meanLufs(levels, s.ids) })).filter((x) => x.v !== null).sort((a, z) => z.v! - a.v!);
      if (loud.length > 1) {
        const only = facts.find((f) => f.name === loud[0].s.name)?.onlyHere.length ?? 0;
        parts.push(` The loudest part is the ${loud[0].s.name.toLowerCase()}`, only ? `: ${plural(only, "track")} ${only === 1 ? "plays" : "play"} only there.` : ".");
      }
    }
    const blocks: Block[] = [{ kind: "p", parts }];
    const tags: { text: string; tone: "ai" | null }[] = [];
    const noted = new Set(p.ai.notes.map((n) => n.track).filter(Boolean)).size;
    if (noted) tags.push({ text: `${plural(noted, "track")} with a note from the assistant`, tone: "ai" });
    const locked = p.tracks.filter((t) => t.locked).length;
    if (locked) tags.push({ text: `${locked} locked`, tone: null });
    const autos = p.tracks.filter((t) => t.automation.some((l) => l.points.length > 0)).length;
    if (autos) tags.push({ text: `${autos} automated`, tone: null });
    if (untouched && audio.length) tags.push({ text: "0 groups", tone: null }, { text: "0 blocks working", tone: null });
    if (tags.length) blocks.push({ kind: "tags", tags });
    sections.push({ id: "short", nav: "In short", title: "In short", hint: null, blocks });
  }

  // How it is built.
  if (audio.length && !untouched) {
    const blocks: Block[] = [];
    if (groups.length) {
      const body: Part[] = [];
      groups.forEach((g, i) => {
        const direct = p.tracks.filter((t) => parentOf(p, t)?.id === g.id);
        const on = working(g);
        if (i) body.push(" ");
        body.push(...tx`${nm(g)} takes ${names(direct)}`);
        if (on.length) body.push(` and treats them as one: ${on.map((x) => low(blockName(g.chain, x.id))).join(", ")}, one fader for all.`);
        else body.push(": one fader moves them together.");
      });
      blocks.push({ kind: "item", icon: "group", head: [b(`${groups.length} `), term(groups.length === 1 ? "group" : "groups", "group")], hint: null, body });
    }
    if (returns.length) {
      const body: Part[] = [];
      returns.forEach((r, i) => {
        const n = sendersOf(p, r).length;
        if (i) body.push(" ");
        body.push(nm(r), ` is ${r.ret ? returnWords(r.ret).replace(/^A /, "a ").replace(/\.$/, "") : "a return"}: ${n ? `${plural(n, "track")} ${n === 1 ? "sends" : "send"} it a copy of ${n === 1 ? "itself" : "themselves"}` : "nothing sends to it yet"}.`);
      });
      body.push(" Only the effect comes back into the mix.");
      blocks.push({ kind: "item", icon: "wave", head: [b(`${returns.length} `), term(returns.length === 1 ? "shared effect" : "shared effects", "shared effect")], hint: "returns", body });
    }
    const direct = audio.filter((t) => !parentOf(p, t));
    if (direct.length && groups.length) blocks.push({ kind: "item", icon: "right", head: [b(`${plural(direct.length, "track")} ${direct.length === 1 ? "goes" : "go"} straight to the mix bus`)], hint: null, body: names(direct, 12) });
    if (blocks.length) sections.push({ id: "structure", nav: "Structure", title: "How it is built", hint: null, blocks });
  }

  // Who is in front.
  if (audio.length) {
    if (levels === null) sections.push({ id: "balance", nav: "Balance", title: "Who is in front", hint: "loudness of each family", blocks: [{ kind: "pending", text: "Measuring how loud each family comes out of the mix. The rest of this page does not wait for it." }] });
    else if (fams.length) {
      const top = fams[0].level_lu!;
      const mix = levels.mix_lufs!;
      const bars: Bar[] = fams.map((f) => {
        const first = p.tracks.find((t) => t.id === f.tracks[0]);
        return { label: familyName(f.name), value: barOf(f.level_lu!, top), text: lufs(mix + f.level_lu!), tint: first ? tintOf(first) : null, accent: false };
      });
      const rets = levels.returns.filter((r) => r.level_lu !== null);
      if (rets.length) {
        const sum = 10 * Math.log10(rets.reduce((a, r) => a + 10 ** (r.level_lu! / 10), 0));
        bars.push({ label: "Shared effects", value: barOf(sum, top), text: lufs(mix + sum), tint: "tb", accent: false });
      }
      const parts: Part[] = ["How loud each family is in the mix, over the whole song."];
      if (fams.length > 1) {
        const last = fams[fams.length - 1];
        parts.push(` ${familyName(fams[0].name)} lead${FAMILY_LABEL[fams[0].name]?.plural ? "" : "s"} by ${n1(top - fams[1].level_lu!)} `, term("LU"), `; ${familyName(last.name).toLowerCase()} ${FAMILY_LABEL[last.name]?.plural ? "sit" : "sits"} ${n1(top - last.level_lu!)} LU behind.`);
      }
      sections.push({ id: "balance", nav: "Balance", title: "Who is in front", hint: "loudness of each family", blocks: [{ kind: "bars", bars }, { kind: "p", parts }] });
    }
  }

  // Left to right.
  if (audio.length) {
    const side = audio.filter((t) => Math.abs(t.chain.pan) >= 0.02).sort((a, z) => Math.abs(z.chain.pan) - Math.abs(a.chain.pan));
    const parts: Part[] = [];
    if (!side.length) parts.push(audio.length === 1 ? "The track is in the centre." : "Every track is in the centre.");
    else {
      side.slice(0, 6).forEach((t, i) => {
        if (i) parts.push(", ");
        parts.push(nm(t), ` ${Math.round(Math.abs(t.chain.pan) * 100)} % ${t.chain.pan < 0 ? "left" : "right"}`);
      });
      if (side.length > 6) parts.push(`, and ${side.length - 6} more off centre`);
      const mid = audio.length - side.length;
      parts.push(mid ? `. The other ${plural(mid, "track")} ${mid === 1 ? "is" : "are"} in the centre.` : ".");
    }
    sections.push({ id: "pan", nav: "Pan", title: "Left to right", hint: null, blocks: [{ kind: "pan", dots: audio.map((t) => ({ id: t.id, name: t.name, tint: tintOf(t), pan: t.chain.pan })) }, { kind: "p", parts }] });
  }

  // Space.
  {
    const blocks: Block[] = [];
    for (const r of returns) {
      const s = sendersOf(p, r);
      if (!s.length) continue;
      const parts: Part[] = [];
      s.slice(0, 6).forEach((x, i) => {
        if (i === 0) parts.push(...tx`${nm(x.t)} is the wettest in ${nm(r)} (${dB(x.db)})`);
        else parts.push(i === 1 ? ", then " : ", ", nm(x.t), ` (${dB(x.db)})`);
      });
      if (s.length > 6) parts.push(` and ${s.length - 6} more`);
      parts.push(returnKind(r) === "reverb" ? ": the more a track sends, the further back it sounds." : ": the more a track sends, the clearer its echo.");
      blocks.push({ kind: "p", parts });
    }
    const dry = audio.filter((t) => !t.sends.length);
    if (blocks.length && dry.length) blocks.push({ kind: "p", parts: tx`${names(dry, 5)} ${dry.length === 1 ? "sends" : "send"} nothing: ${dry.length === 1 ? "it stays" : "they stay"} ${term("dry")} and close.` });
    if (blocks.length) sections.push({ id: "space", nav: "Space", title: "Space", hint: null, blocks });
  }

  // Who reacts to whom.
  if (keys.length) {
    sections.push({
      id: "react",
      nav: "Reacts",
      title: "Who reacts to whom",
      hint: null,
      blocks: keys.map((k) => ({
        kind: "p" as const,
        parts:
          k.fx.type === "compressor"
            ? tx`The ${low(k.block)} of ${nm(k.t)} ${term("listens to", "sidechain")} ${nm(k.src)}: each time ${k.src.name} plays, ${k.t.name} is turned down for a moment, so the two do not pile up.`
            : tx`The ${low(k.block)} of ${nm(k.t)} ${term("listens to", "sidechain")} ${nm(k.src)}: it moves only while ${k.src.name} plays, to leave room for it.`,
      })),
    });
  }

  // What changes along the song.
  if (secs.length > 1 && audio.length) {
    const blocks: Block[] = [];
    const track = (id: string) => p.tracks.find((t) => t.id === id)!;
    for (const f of facts) {
      const body: Part[] = [];
      if (f.onlyHere.length) body.push(...tx`${names(f.onlyHere.map(track), 5)} ${f.onlyHere.length === 1 ? "plays" : "play"} only here. `);
      for (const c of f.changes) body.push(...tx`${nm(track(c.track))} is ${abs1(c.delta)} dB ${c.delta > 0 ? "louder" : "quieter"}. `);
      for (const x of f.blocks) body.push(...tx`${nm(track(x.track))} has its ${low(x.block)} on only here. `);
      if (f.silent.length && f.silent.length <= Math.max(2, f.total / 3)) body.push(...tx`${names(f.silent.map(track), 5)} ${f.silent.length === 1 ? "is" : "are"} silent. `);
      if (!body.length) continue;
      blocks.push({ kind: "item", icon: null, head: [b(f.name)], hint: f.spans.map(([a]) => clock(a, rate)).join(" · "), body });
    }
    const still = p.tracks.filter((t) => !t.automation.some((l) => l.points.length > 0)).length;
    if (blocks.length) {
      blocks.push({ kind: "p", parts: [`${plural(still, "track, group or effect", "tracks, groups and effects")} ${still === 1 ? "keeps" : "keep"} the same settings from start to end.`], faint: true });
      sections.push({ id: "time", nav: "Over time", title: "What changes along the song", hint: null, blocks });
    }
  }

  // Reasons.
  {
    const blocks = reasonsOf(p);
    if (blocks.length) sections.push({ id: "reasons", nav: "Reasons", title: "Reasons", hint: null, blocks: [...blocks, { kind: "p", parts: [REASONS_FOOT], faint: true }] });
    else if (untouched && audio.length) sections.push({ id: "reasons", nav: "Start", title: "Where to start", hint: null, blocks: [{ kind: "p", parts: tx`This page describes the mix; it does not judge it. For a first balance, close it and use ${b("Auto mix")} in the assistant, or move the faders: the map and this text follow every change.` }] });
  }
  return { title: "Explain this mix", sections };
}

// ---------- one track, group or return ----------
function chainSteps(p: Project, t: Track): Block[] {
  const steps: Step[] = [];
  const off: string[] = [];
  for (const x of t.chain.blocks) {
    const name = blockName(t.chain, x.id);
    // A bypass lane decides where the block plays, whatever its switch says at rest (AI-6).
    const lane = t.automation.some((l) => l.param === `bypass.${x.id}` && l.points.length > 0);
    const where = lane ? playsIn(t, x.id, p.sections) : null;
    const state = lane && where !== "Never" ? blockState({ ...x.fx, bypass: false }) : where === "Never" ? "off" : blockState(x.fx);
    if (state === "off") {
      off.push(name);
      continue;
    }
    const src = sidechainsOf(x.fx).map((id) => p.tracks.find((s) => s.id === id)).find((s) => !!s);
    const body = state === "neutral" ? ["On, but set flat: it changes nothing."] : blockWords(x.fx, p);
    if (where) body.push(` On only in: ${where}.`);
    steps.push({ sig: INFO[x.fx.type].mark, state: state === "on" ? "on" : "neutral", keyTint: state === "on" && src ? tintOf(src) : null, name, value: blockSummary(x.fx), body });
  }
  const lane = t.automation.find((l) => l.param === "fader" && l.points.length > 0);
  const dest = parentOf(p, t);
  const fader: Part[] = [dest ? `Its level into ${dest.name}.` : "Its level in the mix."];
  if (lane) fader.push(" ", { tone: lane.author === "ai" ? "ai" : "acc", text: lane.author === "ai" ? "Automated by the assistant" : "Automated by hand" }, ": it moves along the song.");
  steps.push({ sig: "LVL", state: "neutral", keyTint: null, name: "Fader", value: dB(t.chain.fader_db), body: fader });
  const out: Block[] = [{ kind: "steps", steps }];
  if (off.length) out.push({ kind: "p", parts: [`Off on this ${t.kind === "audio" ? "track" : t.kind}: ${off.join(", ")}.`], faint: true });
  return out;
}

function noteOf(p: Project, t: Track): Block[] {
  const n = p.ai.notes.find((x) => x.track === t.id);
  if (!n) return [];
  return [{ kind: "note", number: n.number, title: "The assistant’s reason", text: n.text, foot: "From the last proposal applied. Changes made by hand since have no reason attached." }];
}

export function explainElement(p: Project, id: string, levels: MixLevels | null): Doc | null {
  const t = p.tracks.find((x) => x.id === id);
  if (!t) return null;
  const rate = p.sample_rate ?? 48000;
  const sections: DocSection[] = [];
  const dest = parentOf(p, t);
  const destParts = (): Part[] => {
    if (!dest) return [b("straight to the mix bus")];
    const next = parentOf(p, dest);
    return tx`into ${nm(dest)}, which goes ${next ? tx`into ${nm(next)}` : "to the mix bus"}`;
  };
  const sendParts = (): Part[] => {
    const s = t.sends.map((x) => ({ r: p.tracks.find((r) => r.id === x.target), db: x.level_db })).filter((x) => !!x.r);
    if (!s.length) return returnsOf(p).length ? [" It sends nothing to the shared effects: it stays dry."] : [];
    const chips: Part[] = s.flatMap((x, i) => [i ? (i === s.length - 1 ? " and " : ", ") : "", nm(x.r!), ` (${dB(x.db)})`]);
    return tx` It also sends a copy of itself to ${chips}.`;
  };

  if (t.kind === "return") {
    const senders = sendersOf(p, t);
    sections.push({ id: "what", nav: "What", title: "What it is", hint: null, blocks: [{ kind: "p", parts: tx`A ${b("shared effect")}. ${t.ret ? returnWords(t.ret) : ""} Tracks do not pass through it: each one ${term("sends", "send")} a copy, and only the effect comes back, ${dest ? tx`into ${nm(dest)}` : "into the mix bus"}, at ${dB(t.chain.fader_db)}.` }] });
    if (senders.length) {
      const top = senders[0].db;
      const blocks: Block[] = [{ kind: "bars", bars: senders.map((s) => ({ label: s.t.name, value: Math.max(0.04, Math.min(1, 1 - (top - s.db) / 30)), text: dB(s.db), tint: tintOf(s.t), accent: false })) }];
      const others = p.tracks.filter((x) => x.kind !== "return").length - senders.length;
      blocks.push({ kind: "p", parts: senders.length > 1 ? tx`${nm(senders[0].t)} is the wettest, ${nm(senders[senders.length - 1].t)} the driest.${others > 0 ? ` The other ${plural(others, "track or group", "tracks and groups")} send nothing here.` : ""}` : tx`Only ${nm(senders[0].t)} sends here.` });
      sections.push({ id: "senders", nav: "Senders", title: "Who sends here", hint: plural(senders.length, "track"), blocks });
    } else sections.push({ id: "senders", nav: "Senders", title: "Who sends here", hint: null, blocks: [{ kind: "p", parts: ["Nothing sends here yet: it adds nothing to the mix."] }] });
    sections.push({ id: "does", nav: "Effect", title: "What it does for the mix", hint: null, blocks: [{ kind: "p", parts: [returnKind(t) === "reverb" ? "Tracks that share a reverb sound as if they were in the same room. The more a track sends, the further back it sits." : "A delay repeats what it receives, behind the sound. The more a track sends, the clearer its echo."] }] });
    if (t.chain.blocks.some((x) => blockState(x.fx) !== "off")) sections.push({ id: "chain", nav: "Chain", title: "What happens after the effect, in order", hint: null, blocks: chainSteps(p, t) });
  } else {
    const where: Part[] = t.kind === "group" ? tx`${nm(t)} takes ${names(p.tracks.filter((x) => parentOf(p, x)?.id === t.id))} and sends them on ${destParts()} as one.` : tx`${nm(t)} goes ${destParts()}${dest ? "." : tx`: it is not part of a ${term("group")}.`}`;
    where.push(...sendParts());
    sections.push({ id: "where", nav: "Path", title: "Where it goes", hint: null, blocks: [{ kind: "p", parts: where }] });

    const place: Part[] = [];
    if (t.kind === "audio") {
      const pan = Math.abs(t.chain.pan) < 0.02 ? "in the centre" : `${Math.round(Math.abs(t.chain.pan) * 100)} % to the ${t.chain.pan < 0 ? "left" : "right"} (${formatPan(t.chain.pan)})`;
      place.push(`Fader at ${dB(t.chain.fader_db)}, ${pan}.`);
      const fam = hasLevels(levels) ? levels.families.find((f) => f.tracks.includes(t.id)) : undefined;
      if (fam && fam.level_lu !== null) {
        const others = fam.tracks.length - 1;
        place.push(` ${others ? `With ${plural(others, "other track")} it makes up` : "It is"} the ${familyName(fam.name).toLowerCase()}, which ${FAMILY_LABEL[fam.name]?.plural && others ? "sit" : "sits"} ${abs1(fam.level_lu)} `, term("LU"), ` ${fam.level_lu < 0 ? "below" : "above"} the whole mix.`);
      }
      const secs = sectionGroups(p);
      if (secs.length > 1) {
        const all = [...p.sections].sort((a, z) => a.start - z.start);
        const not = all.filter((s) => !playsBetween(t, s.start, s.end, rate));
        if (!not.length) place.push(" It plays in every section.");
        else if (not.length === all.length) place.push(" It plays in no section.");
        else place.push(` It plays in ${all.length - not.length} of the ${all.length} sections: not in ${[...new Set(not.map((s) => `the ${s.name.toLowerCase()}`))].join(", ").replace(/, ([^,]*)$/, " or $1")}.`);
      }
    } else {
      place.push(`Group fader at ${dB(t.chain.fader_db)}: it moves ${plural(membersOf(p, t.id).filter((x) => x.kind === "audio").length, "track")} together.`);
    }
    sections.push({ id: "place", nav: "Place", title: "Its place in the mix", hint: null, blocks: [{ kind: "p", parts: place }] });

    const listens = keysOf(p).filter((k) => k.t.id === t.id);
    const heard = keysOf(p).filter((k) => k.src.id === t.id);
    if (listens.length || heard.length) {
      const parts: Part[] = [];
      for (const k of listens) parts.push(...tx`Its ${low(k.block)} listens to ${nm(k.src)} through a ${term("sidechain")}: it works when ${k.src.name} plays. `);
      for (const k of heard) parts.push(...tx`${nm(k.t)} listens to it: its ${low(k.block)} works when ${t.name} plays. `);
      sections.push({ id: "react", nav: "Reactions", title: "Who it reacts to", hint: null, blocks: [{ kind: "p", parts }] });
    }
    sections.push({ id: "chain", nav: "Chain", title: "What happens to it, in order", hint: null, blocks: chainSteps(p, t) });
  }
  const note = noteOf(p, t);
  if (note.length) sections.push({ id: "reasons", nav: "Reason", title: "Why it is set this way", hint: null, blocks: note });
  return { title: t.name, sections };
}

// ---------- one section of the song ----------
export function explainSection(p: Project, name: string, levels: MixLevels | null): Doc | null {
  const f = sectionFacts(p, name);
  if (!f) return null;
  const track = (id: string) => p.tracks.find((t) => t.id === id)!;
  const sections: DocSection[] = [];
  const plays: Part[] = [b(`${f.playing.length} of the ${plural(f.total, "track")}.`)];
  if (f.onlyHere.length) plays.push(...tx` ${names(f.onlyHere.map(track))} ${f.onlyHere.length === 1 ? "plays" : "play"} ${b("only")} here.`);
  if (f.silent.length && f.silent.length <= f.total / 2) plays.push(...tx` ${names(f.silent.map(track))} ${f.silent.length === 1 ? "is" : "are"} silent here.`);
  sections.push({ id: "plays", nav: "Plays", title: "What plays here", hint: null, blocks: [{ kind: "p", parts: plays }] });

  const diff: Block[] = [];
  for (const c of f.changes) diff.push({ kind: "item", icon: null, head: [nm(track(c.track)), b(` ${abs1(c.delta)} dB ${c.delta > 0 ? "louder" : "quieter"}`)], hint: null, body: [`Fader ${"automation"} written ${c.by === "ai" ? "by the assistant" : "by hand"}, compared with the other sections.`] });
  for (const x of f.blocks) diff.push({ kind: "item", icon: null, head: [nm(track(x.track)), b(` ${x.block} on`)], hint: null, body: ["The block is on only in this section and bypassed everywhere else."] });
  if (!diff.length) diff.push({ kind: "p", parts: ["Nothing is set differently here: faders and blocks are as in the rest of the song."] });
  else diff.push({ kind: "p", parts: ["Everything else is set as in the rest of the song."], faint: true });
  sections.push({ id: "diff", nav: "Differences", title: "What is set differently", hint: null, blocks: diff });

  const groups = sectionGroups(p);
  if (levels === null && groups.length > 1) sections.push({ id: "compare", nav: "Loudness", title: "How it compares", hint: "loudness of the mix per section", blocks: [{ kind: "pending", text: "Measuring how loud each section is." }] });
  else if (hasLevels(levels) && groups.length > 1) {
    const rows = groups.map((g) => ({ g, v: meanLufs(levels, g.ids) })).filter((x) => x.v !== null).sort((a, z) => z.v! - a.v!);
    const me = rows.find((r) => r.g.name === name);
    if (rows.length > 1 && me) {
      const top = rows[0].v!;
      const bars: Bar[] = rows.map((r) => ({ label: r.g.name, value: barOf(r.v!, top), text: lufs(r.v!), tint: null, accent: r.g.name === name }));
      const text = me === rows[0] ? `The loudest section: ${n1(top - rows[1].v!)} LU above ${rows[1].g.name.toLowerCase()}.` : `${n1(top - me.v!)} LU below ${rows[0].g.name.toLowerCase()}, the loudest section.`;
      sections.push({ id: "compare", nav: "Loudness", title: "How it compares", hint: "loudness of the mix per section", blocks: [{ kind: "bars", bars }, { kind: "p", parts: [text] }] });
    }
  }
  return { title: name, sections };
}

// ---------- plain text (Copy as text) ----------
const partText = (x: Part): string => (typeof x === "string" ? x : "b" in x ? x.b : "name" in x ? x.name : x.text);
const run = (parts: Part[]) => parts.map(partText).join("").replace(/\s+/g, " ").trim();
export function toPlainText(doc: Doc): string {
  const out: string[] = [doc.title, ""];
  for (const s of doc.sections) {
    out.push(s.title.toUpperCase());
    for (const x of s.blocks) {
      if (x.kind === "p") out.push(run(x.parts));
      else if (x.kind === "tags") out.push(x.tags.map((t) => t.text).join(" · "));
      else if (x.kind === "item") out.push(`${run(x.head)}${x.hint ? ` (${x.hint})` : ""}: ${run(x.body)}`);
      else if (x.kind === "bars") out.push(...x.bars.map((r) => `- ${r.label}: ${r.text}`));
      else if (x.kind === "pan") out.push(...x.dots.filter((d) => Math.abs(d.pan) >= 0.02).map((d) => `- ${d.name}: ${formatPan(d.pan)}`));
      else if (x.kind === "steps") out.push(...x.steps.map((st, i) => `${i + 1}. ${st.name} (${st.value}): ${run(st.body)}`));
      else if (x.kind === "note") out.push(`${x.number !== null ? `[${x.number}] ` : ""}${x.title}: “${x.text}”`);
      else out.push(x.text);
    }
    out.push("");
  }
  return out.join("\n").trimEnd() + "\n";
}

export { FAMILY_ORDER, familyOf };
